  "Остаток: {n}": {"en":"In stock: {n}","ru":"Остаток: {n}","uz":"Qoldiq: {n}"},
  "Позиций: {n} · Итого: {total} UZS": {"en":"Items: {n} · Total: {total} UZS","ru":"Позиций: {n} · Итого: {total} UZS","uz":"Pozitsiyalar: {n} · Jami: {total} UZS"},
  "Поставщиков: {n}": {"en":"Suppliers: {n}","ru":"Поставщиков: {n}","uz":"Yetkazib beruvchilar: {n}"},
  "Не удалось загрузить поставщиков: {msg}": {"en":"Could not load the suppliers: {msg}","ru":"Не удалось загрузить поставщиков: {msg}","uz":"Yetkazib beruvchilarni yuklab bo'lmadi: {msg}"},
  "Не удалось загрузить карточки: {msg}": {"en":"Could not load the cards: {msg}","ru":"Не удалось загрузить карточки: {msg}","uz":"Kartochkalarni yuklab bo'lmadi: {msg}"},
