  "Не удалось подтвердить: {msg}": {"en":"Could not confirm: {msg}","ru":"Не удалось подтвердить: {msg}","uz":"Tasdiqlab bo'lmadi: {msg}"},
  "Не удалось отклонить: {msg}": {"en":"Could not decline: {msg}","ru":"Не удалось отклонить: {msg}","uz":"Rad etib bo'lmadi: {msg}"},
