  "(заблокировали бота: {n})": {"en":"(blocked the bot: {n})","ru":"(заблокировали бота: {n})","uz":"(botni blokladi: {n})"},
  "✅ Готово · {when}": {"en":"✅ Done · {when}","ru":"✅ Готово · {when}","uz":"✅ Tayyor · {when}"},
  "бот подтверждён": {"en":"bot confirmed","ru":"бот подтверждён","uz":"bot tasdiqlandi"},
  "Связь с Telegram установлена · {who}": {"en":"Telegram connection established · {who}","ru":"Связь с Telegram установлена · {who}","uz":"Telegram bilan aloqa o'rnatildi · {who}"},
  "Последняя проверка: {when}": {"en":"Last check: {when}","ru":"Последняя проверка: {when}","uz":"Oxirgi tekshiruv: {when}"},
  "Сохранённый токен: …{hint} (заменить)": {"en":"Saved token: …{hint} (replace)","ru":"Сохранённый токен: …{hint} (заменить)","uz":"Saqlangan token: …{hint} (almashtirish)"},
  "Токен сохранён, но Telegram его не принял: {msg}": {"en":"The token is saved, but Telegram rejected it: {msg}","ru":"Токен сохранён, но Telegram его не принял: {msg}","uz":"Token saqlandi, lekin Telegram uni qabul qilmadi: {msg}"},
  "Готово! Бот @{bot} включён и отвечает пациентам.": {"en":"Done! The bot @{bot} is on and answering patients.","ru":"Готово! Бот @{bot} включён и отвечает пациентам.","uz":"Tayyor! @{bot} bot yoqildi va bemorlarga javob bermoqda."},
