  "Выберите врача — {n} услуг(и) ждут": {"en":"Choose a doctor — {n} service(s) are waiting","ru":"Выберите врача — {n} услуг(и) ждут","uz":"Shifokorni tanlang — {n} xizmat kutmoqda"},
  "выберите врача и время для услуг, где нужен врач": {"en":"choose a doctor and time for the services that need one","ru":"выберите врача и время для услуг, где нужен врач","uz":"shifokor kerak bo'lgan xizmatlarga shifokor va vaqt tanlang"},
