  "Выполняем…": {"en":"Working…","ru":"Выполняем…","uz":"Bajarilmoqda…"},
  "Выставить в счёт пациенту": {"en":"Bill to the patient","ru":"Выставить в счёт пациенту","uz":"Bemor hisob-fakturasiga chiqarish"},
  "выставлено": {"en":"billed","ru":"выставлено","uz":"chiqarilgan"},
