  "Первичный осмотр и план лечения": {"en": "Initial examination and treatment plan", "ru": "Первичный осмотр и план лечения", "uz": "Birlamchi ko'rik va davolash rejasi"},
  "Обоснование клинического диагноза": {"en": "Justification of the clinical diagnosis", "ru": "Обоснование клинического диагноза", "uz": "Klinik tashxis asoslanishi"},
