  "при выписке": {"en": "at discharge", "ru": "при выписке", "uz": "chiqarish paytida"},
  "срок пойдёт с момента размещения на койке": {"en": "the clock starts when the patient is placed in a bed", "ru": "срок пойдёт с момента размещения на койке", "uz": "muddat bemor koykaga joylashtirilganidan boshlanadi"},
  "только при операции": {"en": "only if there is an operation", "ru": "только при операции", "uz": "faqat operatsiya bo'lsa"},
